mapper.select:
select count(1) from (select r.riskid from TBL_RISK_RISKMARKING m left join TBL_RISK_ASSPLAN_RISK r
 on r.assriskid=m.assriskid left join tbl_risk s on s.riskid=r.riskid where 1=1

  and m.asssatus=#{type} 


  and s.unit=#{orgid} 

  and m.assriskid is not null  group by   r.riskid  ) dual

select count(1) from (select r.riskid from TBL_RISK_RISKMARKING m left join TBL_RISK_ASSPLAN_RISK r on r.assriskid=m.assriskid left join tbl_risk s on s.riskid=r.riskid where s.closestatus=1
and s.unit=#{orgid}
and m.assriskid is not null group by r.riskid ) dual
